'use client';

import * as React from 'react';
import { useEffect, useState } from 'react';
import { motion, AnimatePresence, useScroll } from 'motion/react';
import { Navbar, NavbarProps } from '@/components/ui/navbar';

export interface FloatingNavbarProps extends NavbarProps {
  /**
   * Scroll threshold in pixels before navbar appears
   * @default 100
   */
  scrollThreshold?: number;
}

/**
 * FloatingNavbar Component
 *
 * A scroll-aware navbar that appears when the user scrolls down past a threshold
 * and disappears when scrolling back to the top. Uses Motion for smooth animations.
 *
 * NOTE: This component uses the existing Navbar component as its base and adds
 * scroll-triggered visibility logic with smooth slide-down/slide-up animations.
 *
 * @example
 * <FloatingNavbar
 *   logo={<Logo />}
 *   scrollThreshold={100}
 *   ctaText="Get Started"
 *   onCtaClick={() => console.log('CTA clicked')}
 * />
 */
export const FloatingNavbar = React.forwardRef<
  HTMLElement,
  FloatingNavbarProps
>(({ scrollThreshold = 100, ...navbarProps }, ref) => {
  const [isVisible, setIsVisible] = useState(false);
  const { scrollY } = useScroll();

  useEffect(() => {
    // NOTE: Subscribe to scroll position changes
    // Show navbar when scrolled past threshold, hide when back at top
    const unsubscribe = scrollY.on('change', (latest) => {
      if (latest > scrollThreshold) {
        setIsVisible(true);
      } else {
        setIsVisible(false);
      }
    });

    return () => unsubscribe();
  }, [scrollY, scrollThreshold]);

  return (
    <AnimatePresence mode="wait">
      {isVisible && (
        <motion.div
          key="floating-navbar"
          initial={{ y: -100, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: -100, opacity: 0 }}
          transition={{
            duration: 0.3,
            ease: [0.25, 0.46, 0.45, 0.94], // Smooth easeOutCubic
          }}
          className="fixed top-0 right-0 left-0 z-[100]"
        >
          <Navbar
            ref={ref}
            {...navbarProps}
            className="shadow-lg"
            backgroundColor="bg-background/95 backdrop-blur-md"
          />
        </motion.div>
      )}
    </AnimatePresence>
  );
});

FloatingNavbar.displayName = 'FloatingNavbar';

// Demo component for testing
export function FloatingNavbarDemo() {
  return (
    <>
      <FloatingNavbar
        ctaText="Get Started"
        onCtaClick={() => console.log('CTA clicked')}
      />
      {/* Demo content to enable scrolling */}
      <div className="h-[200vh] space-y-4 p-8">
        <div className="h-screen bg-gradient-to-b from-blue-100 to-purple-100">
          <div className="flex h-full items-center justify-center">
            <h1 className="text-4xl font-bold">Scroll down to see navbar</h1>
          </div>
        </div>
        <div className="h-screen bg-gradient-to-b from-purple-100 to-pink-100">
          <div className="flex h-full items-center justify-center">
            <h1 className="text-4xl font-bold">Keep scrolling...</h1>
          </div>
        </div>
      </div>
    </>
  );
}
